let currentQuestion = 0;
let score = 0;
let userAnswers = [];
let currentTopic = 1;
let questions = [];
let currentSectionId = null;
let currentClassLevel = 7;
let testCompleted = false;

function showNotification(message, type) {
    const notification = document.createElement('div');
    notification.className = 'notification';
    notification.textContent = message;
    notification.style.cssText = 'position:fixed;top:100px;right:30px;padding:16px 24px;border-radius:12px;font-weight:600;font-size:14px;color:white;z-index:10000;background:linear-gradient(135deg, #11998e 0%, #38ef7d 100%);box-shadow:0 8px 24px rgba(0,0,0,0.2);';
    document.body.appendChild(notification);
    setTimeout(function() { notification.remove(); }, 3000);
}

document.addEventListener("DOMContentLoaded", function() {
    var topicNumber = sessionStorage.getItem("topicNumber");
    var topicTitle = sessionStorage.getItem("topicTitle") || "Тест";
    var sectionId = sessionStorage.getItem("sectionId");
    var classLevel = sessionStorage.getItem("classLevel");
    if (sectionId) currentSectionId = parseInt(sectionId);
    if (classLevel) currentClassLevel = parseInt(classLevel);
    topicNumber = topicNumber || "1";
    currentTopic = topicNumber;
    questions = testQuestions[topicNumber] || testQuestions["1"];
    var titleEl = document.getElementById("testTitle");
    if (titleEl) titleEl.textContent = topicTitle + " - Тест";
    loadQuestion();
    var prevBtn = document.getElementById("prevBtn");
    var nextBtn = document.getElementById("nextBtn");
    var finishBtn = document.getElementById("finishBtn");
    if (prevBtn) prevBtn.addEventListener("click", previousQuestion);
    if (nextBtn) nextBtn.addEventListener("click", nextQuestion);
    if (finishBtn) finishBtn.addEventListener("click", finishTest);
});

function loadQuestion() {
    if (!questions[currentQuestion]) return;
    var question = questions[currentQuestion];
    var qText = document.getElementById("questionText");
    if (qText) qText.textContent = question.q;
    var answersGrid = document.getElementById("answersGrid");
    if (!answersGrid) return;
    answersGrid.innerHTML = "";
    for (var i = 0; i < question.a.length; i++) {
        var answer = question.a[i];
        var label = document.createElement("label");
        label.className = "answer-option";
        if (userAnswers[currentQuestion] === i) label.classList.add("selected");
        label.innerHTML = '<input type="radio" name="answer" value="' + i + '" ' + (userAnswers[currentQuestion] === i ? 'checked' : '') + '><span class="answer-text">' + answer + '</span>';
        label.addEventListener("change", (function(idx) { return function() { userAnswers[currentQuestion] = idx; updateButtonStates(); }; })(i));
        answersGrid.appendChild(label);
    }
    var qCount = document.getElementById("questionCount");
    if (qCount) qCount.textContent = (currentQuestion + 1) + " / " + questions.length;
    var progressFill = document.getElementById("progressFill");
    if (progressFill) progressFill.style.width = ((currentQuestion + 1) / questions.length) * 100 + "%";
    updateButtonStates();
}

function updateButtonStates() {
    var prevBtn = document.getElementById("prevBtn");
    if (prevBtn) prevBtn.disabled = currentQuestion === 0;
    var nextBtn = document.getElementById("nextBtn");
    var finishBtn = document.getElementById("finishBtn");
    if (currentQuestion === questions.length - 1) {
        if (nextBtn) nextBtn.style.display = "none";
        if (finishBtn) finishBtn.style.display = "flex";
    } else {
        if (nextBtn) nextBtn.style.display = "flex";
        if (finishBtn) finishBtn.style.display = "none";
    }
}

function previousQuestion() { if (currentQuestion > 0) { currentQuestion--; loadQuestion(); } }
function nextQuestion() { if (currentQuestion < questions.length - 1) { currentQuestion++; loadQuestion(); } }

async function finishTest() {
    if (testCompleted) {
        showNotification("Сіз бұл тестті тапсырып қойгансыз!", "warning");
        return;
    }

    var correctCount = 0;
    for (var i = 0; i < userAnswers.length; i++) {
        if (userAnswers[i] === questions[i].correct) correctCount++;
    }
    var percentage = Math.round((correctCount / questions.length) * 100);
    var topicNumber = parseInt(sessionStorage.getItem("topicNumber")) || 1;
    var sectionId = parseInt(sessionStorage.getItem("sectionId")) || 1;
    var classLevel = parseInt(sessionStorage.getItem("classLevel")) || 7;

    console.log("Sending data:", { class_level: classLevel, section_id: sectionId, topic_id: topicNumber, score: correctCount, total: questions.length });

    try {
        var response = await fetch("/api/save-test-result", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                class_level: classLevel,
                section_id: sectionId,
                topic_id: topicNumber,
                score: correctCount,
                total: questions.length
            })
        });

        var result = await response.json();
        console.log("Server response:", result);

        if (result.error) {
            console.error("Server error:", result.error);
            showNotification("Қате: " + result.error, "warning");
        } else {
            testCompleted = true;
            if (result.certificate_code) showNotification("Сертификат алдыныз!", "success");
            showResults(percentage, correctCount);

            // ✅ Жетістіктер жүйесін жаңарту (ОСЫ ЖОЛДЫ ҚОСЫҢЫЗ)
            if (window.AchievementsSystem) {
                setTimeout(async () => {
                    await window.AchievementsSystem.refreshAndCheck();
                }, 500);
            }
        }
    } catch(e) {
        console.error("Fetch error:", e);
        showNotification("Қате орын алды!", "warning");
        showResults(percentage, correctCount);

        // ✅ Қате болса да жаңарту
        if (window.AchievementsSystem) {
            setTimeout(async () => {
                await window.AchievementsSystem.refreshAndCheck();
            }, 500);
        }
    }
}

function showResults(percentage, correctCount) {
    var finalScore = document.getElementById("finalScore");
    if (finalScore) finalScore.textContent = percentage;
    var correctSpan = document.getElementById("correctCount");
    if (correctSpan) correctSpan.textContent = correctCount;
    var incorrectSpan = document.getElementById("incorrectCount");
    if (incorrectSpan) incorrectSpan.textContent = questions.length - correctCount;
    var totalSpan = document.getElementById("totalCount");
    if (totalSpan) totalSpan.textContent = questions.length;

    var message = "";
    if (percentage >= 90) message = "Өте өте жақсы! Сен чемпионсың!";
    else if (percentage >= 70) message = "Жақсы! Тағы жақсарыла ала аласың!";
    else if (percentage >= 50) message = "Орта деңгейде! Қайта оқы!";
    else message = "Жетілдіру қажет!";

    var msgEl = document.getElementById("resultMessage");
    if (msgEl) msgEl.textContent = message;

    var reviewHtml = "";
    for (var i = 0; i < userAnswers.length; i++) {
        var isCorrect = userAnswers[i] === questions[i].correct;
        var statusClass = isCorrect ? "correct" : "incorrect";
        var statusText = isCorrect ? "Дұрыс" : "Қате";
        reviewHtml += '<div class="review-item ' + statusClass + '"><div class="review-number">' + (i+1) + '</div><div class="review-content"><div class="review-question">' + questions[i].q + '</div><div class="review-answer-section"><p><strong>Сіздің жауап:</strong> ' + questions[i].a[userAnswers[i]] + ' (' + statusText + ')</p>' + (!isCorrect ? '<p><strong>Дұрыс жауап:</strong> ' + questions[i].a[questions[i].correct] + '</p>' : "") + '</div></div></div>';
    }
    var reviewEl = document.getElementById("answerReview");
    if (reviewEl) reviewEl.innerHTML = reviewHtml;

    var backBtn = document.getElementById("backToTopicBtn");
    if (backBtn) {
        backBtn.textContent = "📚 Тақырыптарға оралу";
        // ТҮЗЕТУ: sessionStorage-ден sectionId алу
        backBtn.onclick = function() {
            var sectionId = sessionStorage.getItem("sectionId");
            console.log("Returning to section:", sectionId);
            if (sectionId && sectionId !== 'null') {
                window.location.href = "/topic_7_" + sectionId + "bolim";
            } else {
                window.location.href = "/glav";
            }
        };
    }

    var testContainer = document.querySelector(".test-container");
    if (testContainer) testContainer.style.display = "none";

    var modal = document.getElementById("resultsModal");
    if (modal) modal.classList.add("show");
}